187:     // the truck is parked out in the valley — wake up at the driver's door
188:     const hdg = t.heading || 0
189:     player.pos.set(t.x - Math.cos(hdg) * 3.2, 1.62, t.z + Math.sin(hdg) * 3.2)
190:   }
191:   player.yaw = truckInGarage ? 0.58 : Math.atan2(-(t.x - player.pos.x), -(t.z - player.pos.z))
192:   player.pitch = -0.08
