202: function syncWorldFromState() {
203:   const s = game.s
204:   for (const [name, info] of Object.entries(PART_INFO)) {
205:     const installed = !!s.parts[name]
206:     world.truck.setPart(name, installed)
207:     if (installed) {
208:       if (name === 'wheels') world.truck.setPart('wheels', true)
209:       world.truck.makeBolts(name, s.bolts[name] || [])
210:     }
211:     const p = world.pickups[name]
212:     if (p) {
213:       const gone = installed || (s.inventory[name] || 0) > 0
214:       p.taken = gone
215:       p.group.visible = !gone
216:     }
217:   }
218:   world.truck.group.position.set(s.truck.x, 0, s.truck.z)
219:   world.truck.group.rotation.y = s.truck.heading || 0
220:   world.truck.setCargo(!!s.cargo)
221:   if (s.engineRunning) {
222:     syncEngineSound()
223:   }
224:   syncMarkers()
225: }
