231: function syncEngineSound() {
232:   if (game.s.engineRunning) {
233:     sound.startEngine()
234:     sound.revEngine(game.idleRpm(), Math.min(1, game.tuneError().total + game.looseBolts() * 0.05))
235:   } else sound.stopEngine()
236: }
