252: function loop() {
253:   const dt = Math.min(0.05, clock.getDelta())
254:   const t = performance.now() / 1000
255: 
256:   if (mode === 'title') updateTitle(dt, t)
257:   else if (mode === 'dead') { /* keep rendering the dark room */ }
258:   else if (paused || (ui.panel && ui.panel !== 'torque')) {
259:     updateWorldAmbient(dt, t)
260:     ui.tickTorque(dt)
261:     updateHUD()
262:   } else {
263:     if (mode === 'walk') updateWalk(dt, t)
264:     if (mode === 'drive') updateDrive(dt, t)
265:     updateWorldAmbient(dt, t)
266:     ui.tickTorque(dt)
267:     game.tick(dt)
268:     if (game.dead) { mode = 'dead'; paused = true }
269:     updateHUD()
270:     saveAccum += dt
271:     if (saveAccum > 8) { saveAccum = 0; game.save() }
272:     if (ui.panel === 'tune') ui.updateTuneLive()
273:   }
274:   renderer.render(scene, camera)
275:   input.endFrame()
276: }
277: 
278: function updateWorldAmbient(dt, t) {
279:   world.update(dt, t)
280:   if (game.s.engineRunning) {
281:     sound.revEngine(game.idleRpm() + (mode === 'drive' && vehicle === 'truck' ? Math.abs(speed) * 85 : 0), Math.min(1, game.tuneError().total + game.looseBolts() * 0.08))
282:     if (Math.random() < dt * 14) world.puffExhaust()
283:   } else if (vehicle === 'truck' && mode === 'drive') {
284:     sound.revEngine(0, 1)
285:   }
286:   if (Math.random() < dt * 0.06 && !ui.panel) {
287:     // occasional creak / settling
288:     if (Math.random() > 0.5) sound.burst({ freq: 500 + Math.random() * 600, q: 3, dur: 0.18, gain: 0.012, rate: 0.4 })
289:   }
290: }
291: 
292: function updateTitle(dt, t) {
293:   titleTime += dt
294:   camera.fov = 56
295:   camera.updateProjectionMatrix()
296:   camera.position.set(4.55 + Math.sin(t * 0.08) * 0.18, 2.02 + Math.sin(t * 0.11) * 0.04, 4.7 + Math.cos(t * 0.06) * 0.12)
297:   camera.lookAt(0.15, 1.18, -0.55)
298:   world.update(dt, t)
299:   if (game.s.engineRunning) {} // keep title quiet
300: }
301: 
302: function updateWalk(dt, t) {
303:   camera.fov += (64 - camera.fov) * 0.1
304:   camera.updateProjectionMatrix()
305:   const look = input.consumeLook()
306:   if (!ui.panel) {
307:     player.yaw -= look.x * 0.0022
308:     player.pitch -= look.y * 0.0022
309:     player.pitch = Math.max(-1.35, Math.min(1.35, player.pitch))
310:   }
311:   const axis = ui.panel ? { x: 0, y: 0 } : input.axis()
312:   const fatigue = game.s.meters.fatigue
313:   const sprint = input.sprint() && fatigue < 80 && game.s.meters.stamina !== 0
314:   const speedWalk = (sprint ? 4.2 : 2.7) * (1 - Math.min(0.35, fatigue / 280)) * (game.s.health < 35 ? 0.72 : 1)
315:   const forward = tmpV.set(-Math.sin(player.yaw), 0, -Math.cos(player.yaw))
316:   const right = tmpV2.set(Math.cos(player.yaw), 0, -Math.sin(player.yaw))
317:   const wish = new THREE.Vector3()
318:   wish.addScaledVector(forward, -axis.y).addScaledVector(right, axis.x)
319:   if (wish.lengthSq() > 0) wish.normalize().multiplyScalar(speedWalk * dt)
320:   const moved = tryMove(wish.x, wish.z)
321:   const movedLen = Math.hypot(moved.x, moved.z)
322:   player.stepDist += movedLen
323:   if (movedLen > 0.0005) {
324:     player.bob += dt * (sprint ? 10 : 7.2)
325:     if (player.stepDist > 1.6) { player.stepDist = 0; sound.step(sprint ? 1.4 : 1) }
326:   } else {
327:     player.bob *= 0.9
328:   }
329:   const bobY = Math.sin(player.bob) * (sprint ? 0.045 : 0.028)
330:   const bobX = Math.cos(player.bob * 0.5) * 0.018
331:   camera.position.set(player.pos.x + right.x * bobX, player.pos.y + bobY, player.pos.z + right.z * bobX)
332:   camera.rotation.set(player.pitch, player.yaw, Math.sin(player.bob * 0.5) * 0.004)
333: 
334:   updateInteractions(dt)
335:   updateMountHints()
336:   updateVehicleProximity()
337: }
338: 
339: function tryMove(dx, dz) {
340:   const r = 0.26
341:   let mx = 0, mz = 0
342:   if (!blockedAt(player.pos.x + dx, player.pos.z, r)) { player.pos.x += dx; mx = dx }
343:   if (!blockedAt(player.pos.x, player.pos.z + dz, r)) { player.pos.z += dz; mz = dz }
344:   // keep inside the valley
345:   player.pos.x = Math.max(-170, Math.min(170, player.pos.x))
346:   player.pos.z = Math.max(-170, Math.min(170, player.pos.z))
347:   return { x: mx, z: mz }
348: }
349: 
350: function blockedAt(x, z, r) {
351:   for (const c of world.colliders) {
352:     if (x > c.minX - r && x < c.maxX + r && z > c.minZ - r && z < c.maxZ + r) return true
353:   }
354:   for (const tc of world.treeColliders) {
355:     if ((x - tc.x) ** 2 + (z - tc.z) ** 2 < (tc.r + r) ** 2) return true
356:   }
357:   return false
358: }
