360: // ---------------------------------------------------------------- interactions
361: function updateInteractions(dt) {
362:   current = null
363:   if (ui.panel) { ui.setPrompt(''); return }
364:   raycaster.setFromCamera(screenCenter, camera)
365:   const hits = raycaster.intersectObjects(world.interactables, false)
366:   for (const hit of hits) {
367:     if (hit.distance > 3.4) continue
368:     const def = hit.object.userData.interact
369:     if (!def) continue
370:     const resolved = resolveInteraction(def)
371:     if (resolved) { current = resolved; break }
372:   }
373:   jobPrompt = jobInteraction()
374:   if (jobPrompt) {
375:     const held = input.keys.has('KeyE') || ui.actionHeld
376:     if (jobPrompt.enabled) {
377:       if (held) {
378:         holdProgress += dt
379:         if (holdProgress >= jobPrompt.hold) {
380:           holdProgress = 0
381:           completeJobAction(jobPrompt)
382:         }
383:       } else holdProgress = 0
384:     } else holdProgress = 0
385:     ui.setPrompt(jobPrompt.text, { blocked: !jobPrompt.enabled, hold: jobPrompt.enabled ? jobPrompt.hold : 0, progress: holdProgress / jobPrompt.hold, key: 'E' })
386:     return
387:   }
388:   holdProgress = 0
389:   if (current) {
390:     ui.setPrompt(current.blocked ? current.reason : current.text, { blocked: current.blocked })
391:   } else {
392:     ui.setPrompt('')
393:   }
394: }
395: 
396: function updateMountHints() {
397:   if (!world.mountHints) return
398:   for (const [name, sprite] of Object.entries(world.mountHints)) {
399:     sprite.visible = !game.s.parts[name] && (game.s.inventory[name] || 0) > 0
400:     if (sprite.visible) sprite.material.opacity = 0.55 + Math.sin(performance.now() * 0.004) * 0.25
401:   }
402: }
403: 
404: function updateVehicleProximity() {
405:   // no-op placeholder; interactions handle entry
406: }
407: 
408: function resolveInteraction(def) {
409:   const id = def.id
410:   const s = game.s
411:   if (id.startsWith('pickup_')) {
412:     const part = id.slice(7)
413:     if (world.pickups[part]?.taken) return null
414:     return { text: `Pick up ${PART_INFO[part]?.name || def.label}`, action: 'pickup', part, key: 'E' }
415:   }
416:   if (id.startsWith('mount_')) {
417:     const part = id.slice(6)
418:     const info = PART_INFO[part]
419:     if (!info) return null
420:     const inv = s.inventory[part] || 0
421:     if (!s.parts[part]) {
422:       if (!inv) return { text: `Install ${info.name}`, blocked: true, reason: `${info.name} is still in the garage.`, action: 'install', part }
423:       if (tool !== info.tool) return { text: `Install ${info.name}`, blocked: true, reason: `Requires a ${info.tool}mm socket.`, action: 'install', part }
424:       return { text: `Install ${info.name} · ${info.tool}mm`, action: 'install', part }
425:     }
426:     const next = game.nextBolt(part)
427:     if (next < 0) return { text: `${info.name} · at spec`, action: null }
428:     const state = s.bolts[part][next]
429:     const strip = state === 'stripped'
430:     if (tool !== info.tool) return { text: strip ? 'Replace stripped bolt' : `Re-torque ${info.name}`, blocked: true, reason: `Requires a ${info.tool}mm socket.`, action: 'retorque', part, index: next }
431:     if (strip && (s.inventory.boltKit || 0) <= 0) return { text: 'Replace stripped bolt', blocked: true, reason: 'No bolt kit. The parts terminal sells them.', action: 'retorque', part, index: next }
432:     return { text: strip ? 'Replace stripped bolt' : `Torque ${info.name} · bolt ${next + 1}/${info.bolts}`, action: 'retorque', part, index: next }
433:   }
434:   switch (id) {
435:     case 'manual': return { text: 'Read the service log', action: 'manual' }
436:     case 'board': return { text: 'Check the job board', action: 'board' }
437:     case 'store': return { text: 'Use the parts terminal', action: 'store' }
438:     case 'radio': return { text: 'Turn the radio on', action: 'radio' }
439:     case 'cot': return { text: 'Sleep until morning', action: 'sleep' }
440:     case 'sink': return { text: 'Wash up / drink from the tap', action: 'sink' }
441:     case 'food': return { text: 'Eat cold beans', action: 'eat' }
442:     case 'coffee': return { text: 'Pour coffee', action: 'coffee' }
443:     case 'cigarettes': return { text: 'Smoke one', action: 'smoke' }
444:     case 'tune': return { text: 'Tune the engine', action: 'tune' }
445:     case 'ignition':
446:     case 'truck_drive':
447:       if (s.engineRunning) return { text: 'Get into The Patient', action: 'enter_truck' }
448:       return { text: 'Crank the engine', action: 'crank' }
449:     case 'moped_drive': return { text: 'Ride the moped', action: 'enter_moped' }
450:     case 'fuel_tank': {
451:       if ((s.inventory.fuel || 0) <= 0) return { text: 'Fill the fuel tank', blocked: true, reason: 'No fuel can. Buy one at the parts terminal.', action: 'fuel' }
452:       return { text: 'Fill the fuel tank · 1 can', action: 'fuel' }
453:     }
454:     case 'oil_fill': {
455:       if ((s.inventory.oil || 0) <= 0) return { text: 'Fill engine oil', blocked: true, reason: 'No oil. Buy a jug at the parts terminal.', action: 'oil' }
456:       return { text: 'Fill engine oil · 1 jug', action: 'oil' }
457:     }
458:     case 'coolant_fill': {
459:       if ((s.inventory.coolant || 0) <= 0) return { text: 'Fill coolant', blocked: true, reason: 'No antifreeze. Buy a jug at the parts terminal.', action: 'coolant' }
460:       return { text: 'Fill coolant · 1 jug', action: 'coolant' }
461:     }
462:   }
463:   return null
464: }
465: 
466: function doAction() {
467:   if (mode === 'title' || game.dead) return
468:   if (ui.panel) {
469:     return
470:   }
471:   if (mode === 'drive') {
472:     if (jobInteraction()?.enabled) return // hold handled in loop
473:     exitVehicle()
474:     return
475:   }
476:   if (jobPrompt) return
477:   if (!current) return
478:   if (current.blocked) {
479:     sound.error()
480:     ui.toast(current.reason || 'Not now.', 'bad')
481:     game.s.meters.stress = Math.min(100, game.s.meters.stress + 1)
482:     return
483:   }
484:   switch (current.action) {
485:     case 'pickup': pickupPart(current.part); break
486:     case 'install': installPart(current.part); break
487:     case 'retorque': retorque(current.part, current.index); break
488:     case 'manual': ui.openPanel('manual'); break
489:     case 'board': ui.openPanel('board'); break
490:     case 'store': ui.openPanel('store'); break
491:     case 'tune': ui.openPanel('tune'); break
492:     case 'radio': {
493:       const on = sound.toggleRadio()
494:       ui.toast(on ? 'The radio crackles to life. Something slow and sad.' : 'Radio off.')
495:       break
496:     }
497:     case 'sleep': {
498:       const msg = game.sleep()
499:       ui.toast(msg, 'good')
500:       sound.clunk()
501:       break
502:     }
503:     case 'sink': ui.toast(game.wash(), 'good'); break
504:     case 'eat': ui.toast(game.eat(), ''); break
505:     case 'coffee': ui.toast(game.coffee(), ''); break
506:     case 'smoke': ui.toast(game.smoke(), ''); break
507:     case 'crank': {
508:       const res = game.startEngine()
509:       ui.toast(res.msg, res.running ? 'good' : 'bad')
510:       if (res.running) {
511:         syncEngineSound()
