139:     if (m.thirst <= 0) dmg += 0.42
140:     if (m.fatigue >= 100) dmg += 0.15
141:     if (m.stress >= 100) dmg += 0.1
142:     if (dmg > 0) this.damage(dmg * dt, 'Your body gives out')
