144:     if (Math.random() < dt * 0.008 && m.hunger < 12) this.sound?.tone({ freq: 70, dur: 0.4, gain: 0.04, type: 'sine' })
145:     if (this.s.engineRunning && this.s.fluids.fuel > 0) {
146:       this.s.fluids.fuel = clamp(this.s.fluids.fuel - dt * 0.03, 0, 100)
