206:   applyTorque(name, index, value) {
207:     const info = PART_INFO[name]
208:     const [lo, hi] = info.torque
209:     let result
210:     if (value < lo) { result = 'loose'; this.s.stats.loose++ }
211:     else if (value > hi * 1.32) { result = 'stripped'; this.s.stats.stripped++ }
212:     else { result = 'good'; this.s.stats.torques++ }
