255:   // ----- tuning ---------------------------------------------------
256:   tuneError() {
257:     const t = this.s.tune, sp = this.specs
258:     const mix = Math.abs(t.mix - sp.mix) / 1.0
259:     const timing = Math.abs(t.timing - sp.timing) / 7
260:     const valve = Math.abs(t.valve - sp.valve) / 0.1
261:     const avg = (Math.min(1, mix) + Math.min(1, timing) + Math.min(1, valve)) / 3
262:     return { mix, timing, valve, total: avg, score: clamp(1 - avg, 0, 1) }
263:   }
264: 
265:   vacuum() {
266:     const e = this.tuneError()
267:     return Math.max(3, 19.5 - e.total * 15 + (this.s.engineRunning ? Math.sin(performance.now() * 0.002) * 0.35 : 0))
268:   }
269: 
270:   idleRpm() {
