283:     const f = this.s.fluids
284:     if (f.oil < 12) return { ok: false, msg: 'No oil in the crankcase. It will seize.' }
285:     if (f.coolant < 12) return { ok: false, msg: 'The radiator is dry. Fill the coolant.' }
286:     if (f.fuel < 3) return { ok: false, msg: 'The tank is empty. Add fuel.' }
