295:       return { running: false, msg: 'Engine off.' }
296:     }
297:     const ready = this.engineReadiness()
298:     if (!ready.ok) return { running: false, msg: ready.msg }
299:     const e = this.tuneError()
300:     let score = e.score
301:     score -= this.looseBolts() * 0.035
302:     score -= this.strippedBolts() * 0.05
303:     if (score >= 0.52) {
304:       this.s.engineRunning = true
