319:     if (e.mix > 0.5) hint = 'It coughs black smoke and floods. The mixture is off.'
320:     else if (e.timing > 0.5) hint = 'It kicks back against the starter. Timing is wrong.'
321:     else if (e.valve > 0.5) hint = 'It hisses and stumbles. Valves are out of adjustment.'
322:     return { running: false, msg: hint, score }
323:   }
