191:   player.yaw = truckInGarage ? 0.58 : Math.atan2(-(t.x - player.pos.x), -(t.z - player.pos.z))
192:   player.pitch = -0.08
193:   if (loaded && game.s.engineRunning) {
194:     ui.subtitle('The Patient is still warm.\nAnother day in Hollow Creek.', 4200)
195:   }
196:   input.requestLock()
197:   startRender()
198:   updateHUD()
199:   syncMarkers()
200: }
