554: function retorque(part, index) {
555:   const state = game.s.bolts[part]?.[index]
556:   if (state === 'stripped') {
557:     if ((game.s.inventory.boltKit || 0) <= 0) { ui.toast('No bolt kit to replace the stripped stud.', 'bad'); return }
558:     game.s.inventory.boltKit--
