600: function jobInteraction() {
601:   const j = game.s.job
602:   if (!j) return null
603:   const target = game.jobTarget()
604:   if (!target) return null
605:   const pos = mode === 'drive' ? world.truck.group.position : player.pos
606:   if (mode === 'drive' && vehicle === 'moped') {
607:     // moped position instead
608:   }
609:   const p = mode === 'drive' ? (vehicle === 'truck' ? world.truck.group.position : world.truck.group.position) : player.pos
610:   const px = mode === 'drive' ? (vehicle === 'truck' ? world.truck.group.position.x : world.moped.group.position.x) : player.pos.x
611:   const pz = mode === 'drive' ? (vehicle === 'truck' ? world.truck.group.position.z : world.moped.group.position.z) : player.pos.z
612:   const dist = Math.hypot(px - target.x, pz - target.z)
613:   if (dist > 9) return null
614:   if (mode !== 'drive') return { text: `Get a vehicle for ${target.label}`, enabled: false, hold: 0, act: 'none' }
615:   if (Math.abs(speed) > 1.4) return { text: 'Stop the vehicle to load', enabled: false, hold: 0, act: 'none' }
616:   if (j.id === 'firewood' && vehicle !== 'truck') return { text: 'Firewood needs the truck', enabled: false, hold: 0, act: 'none' }
617:   if (j.id === 'firewood' && j.stage === 'to_farm' && game.s.cargo) return { text: 'The truck bed must be empty', enabled: false, hold: 0, act: 'none' }
618:   if (j.stage === 'to_farm') {
619:     return { text: j.id === 'courier' ? 'Drop the crate at Miller farm — hold E' : 'Load firewood at Miller farm — hold E', enabled: true, hold: j.id === 'courier' ? 2.6 : 4.2, act: 'load' }
620:   }
621:   return { text: 'Unload firewood at the store — hold E', enabled: true, hold: 4.2, act: 'unload' }
622: }
