654:     if (!game.wheelsSafe()) { ui.toast('Wheel nuts are loose. Torque them.', 'bad'); return }
655:     vehicle = 'truck'
656:     const t = game.s.truck
657:     world.truck.group.position.set(t.x, 0, t.z)
