339: function tryMove(dx, dz) {
340:   const r = 0.26
341:   let mx = 0, mz = 0
342:   if (!blockedAt(player.pos.x + dx, player.pos.z, r)) { player.pos.x += dx; mx = dx }
343:   if (!blockedAt(player.pos.x, player.pos.z + dz, r)) { player.pos.z += dz; mz = dz }
344:   // keep inside the valley
345:   player.pos.x = Math.max(-170, Math.min(170, player.pos.x))
346:   player.pos.z = Math.max(-170, Math.min(170, player.pos.z))
347:   return { x: mx, z: mz }
348: }
