350: function blockedAt(x, z, r) {
351:   for (const c of world.colliders) {
352:     if (x > c.minX - r && x < c.maxX + r && z > c.minZ - r && z < c.maxZ + r) return true
353:   }
354:   for (const tc of world.treeColliders) {
355:     if ((x - tc.x) ** 2 + (z - tc.z) ** 2 < (tc.r + r) ** 2) return true
356:   }
357:   return false
358: }
