702: function updateDrive(dt, t) {
703:   const axis = input.axis()
704:   const truck = vehicle === 'truck'
705:   const maxFwd = truck ? 13.5 : 9.5
706:   const maxRev = truck ? 4.2 : 2.5
707:   const accel = truck ? 6.2 : 5.2
708:   const brake = 9
709:   const group = truck ? world.truck.group : world.moped.group
710:   const onRoad = isOnRoad(group.position.x, group.position.z)
711:   const drag = onRoad ? 0.7 : 2.4
712: 
713:   // throttle / brake
714:   if (axis.y < -0.1) {
715:     speed += accel * -axis.y * dt * (truck ? 0.9 : 1.1)
716:   } else if (axis.y > 0.1) {
717:     if (speed > 0.2) speed -= brake * axis.y * dt
718:     else speed -= accel * 0.55 * axis.y * dt
719:   } else {
720:     speed -= Math.sign(speed) * drag * dt
721:   }
722:   if (!onRoad) speed -= Math.sign(speed) * 1.3 * dt
723:   speed = Math.max(-maxRev, Math.min(maxFwd, speed))
724:   if (Math.abs(speed) < 0.03) speed = 0
725: 
726:   // steering
727:   const steer = axis.x
728:   const grip = Math.min(1, Math.abs(speed) / 3.2)
729:   if (Math.abs(speed) > 0.05) {
730:     heading += steer * (truck ? 1.5 : 2.1) * dt * grip * Math.sign(speed)
731:   }
732:   if (!onRoad && Math.abs(speed) > 4) {
733:     cameraLook = Math.sin(t * 17) * 0.006 * Math.abs(speed) / 5
734:   } else cameraLook *= 0.9
735: 
736:   // move + collide
737:   const forward = tmpV.set(Math.sin(heading), 0, Math.cos(heading))
738:   const nx = group.position.x + forward.x * speed * dt
739:   const nz = group.position.z + forward.z * speed * dt
740:   let hit = false
