361: function updateInteractions(dt) {
362:   current = null
363:   if (ui.panel) { ui.setPrompt(''); return }
364:   raycaster.setFromCamera(screenCenter, camera)
365:   const hits = raycaster.intersectObjects(world.interactables, false)
366:   for (const hit of hits) {
367:     if (hit.distance > 3.4) continue
368:     const def = hit.object.userData.interact
369:     if (!def) continue
370:     const resolved = resolveInteraction(def)
371:     if (resolved) { current = resolved; break }
372:   }
373:   jobPrompt = jobInteraction()
374:   if (jobPrompt) {
375:     const held = input.keys.has('KeyE') || ui.actionHeld
376:     if (jobPrompt.enabled) {
377:       if (held) {
378:         holdProgress += dt
379:         if (holdProgress >= jobPrompt.hold) {
380:           holdProgress = 0
381:           completeJobAction(jobPrompt)
382:         }
383:       } else holdProgress = 0
384:     } else holdProgress = 0
385:     ui.setPrompt(jobPrompt.text, { blocked: !jobPrompt.enabled, hold: jobPrompt.enabled ? jobPrompt.hold : 0, progress: holdProgress / jobPrompt.hold, key: 'E' })
386:     return
387:   }
388:   holdProgress = 0
389:   if (current) {
390:     ui.setPrompt(current.blocked ? current.reason : current.text, { blocked: current.blocked })
391:   } else {
392:     ui.setPrompt('')
393:   }
394: }
