702: function updateDrive(dt, t) {
703:   const axis = input.axis()
704:   const truck = vehicle === 'truck'
705:   const maxFwd = truck ? 13.5 : 9.5
706:   const maxRev = truck ? 4.2 : 2.5
707:   const accel = truck ? 6.2 : 5.2
708:   const brake = 9
709:   const group = truck ? world.truck.group : world.moped.group
710:   const onRoad = isOnRoad(group.position.x, group.position.z)
711:   const drag = onRoad ? 0.7 : 2.4
712: 
713:   // throttle / brake
714:   if (axis.y < -0.1) {
715:     speed += accel * -axis.y * dt * (truck ? 0.9 : 1.1)
716:   } else if (axis.y > 0.1) {
717:     if (speed > 0.2) speed -= brake * axis.y * dt
718:     else speed -= accel * 0.55 * axis.y * dt
719:   } else {
720:     speed -= Math.sign(speed) * drag * dt
721:   }
722:   if (!onRoad) speed -= Math.sign(speed) * 1.3 * dt
723:   speed = Math.max(-maxRev, Math.min(maxFwd, speed))
724:   if (Math.abs(speed) < 0.03) speed = 0
725: 
726:   // steering
727:   const steer = axis.x
728:   const grip = Math.min(1, Math.abs(speed) / 3.2)
729:   if (Math.abs(speed) > 0.05) {
730:     heading += steer * (truck ? 1.5 : 2.1) * dt * grip * Math.sign(speed)
731:   }
732:   if (!onRoad && Math.abs(speed) > 4) {
733:     cameraLook = Math.sin(t * 17) * 0.006 * Math.abs(speed) / 5
734:   } else cameraLook *= 0.9
735: 
736:   // move + collide
737:   const forward = tmpV.set(Math.sin(heading), 0, Math.cos(heading))
738:   const nx = group.position.x + forward.x * speed * dt
739:   const nz = group.position.z + forward.z * speed * dt
740:   let hit = false
741:   for (const tc of world.treeColliders) {
742:     if ((nx - tc.x) ** 2 + (nz - tc.z) ** 2 < (tc.r + (truck ? 1.25 : 0.6)) ** 2) { hit = true; break }
743:   }
744:   if (nx < -160 || nx > 160 || nz < -160 || nz > 160) hit = true
745:   if (hit) {
746:     if (Math.abs(speed) > 5) {
747:       sound.crash()
748:       game.s.meters.stress = Math.min(100, game.s.meters.stress + 9)
749:       game.s.stats.crashes++
750:       game.damage(Math.min(30, Math.abs(speed) * 0.9), 'The road took you apart')
751:       ui.toast('You hit something solid. The frame shudders.', 'bad')
752:       game.s.meters.fatigue = Math.min(100, game.s.meters.fatigue + 4)
753:     }
754:     speed = -speed * 0.16
755:   } else {
756:     group.position.x = nx
757:     group.position.z = nz
758:   }
759:   group.rotation.y = heading
760:   if (truck) {
761:     group.rotation.z = THREE.MathUtils.lerp(group.rotation.z, -steer * 0.025 * Math.min(1, Math.abs(speed) / 8), 0.08)
762:     group.rotation.x = THREE.MathUtils.lerp(group.rotation.x, -axis.y * 0.008, 0.08)
763:     world.truck.group.updateMatrixWorld()
764:     if (Math.abs(speed) > 0.1) world.truck.update(dt, speed)
765:     game.s.truck = { x: group.position.x, z: group.position.z, heading }
766:     game.s.stats.km += Math.abs(speed) * dt / 1000
767:     sound.revEngine(game.idleRpm() + Math.abs(speed) * 95, Math.min(1, game.tuneError().total + game.looseBolts() * 0.04))
768:     if (Math.abs(speed) > 2 && Math.random() < dt * 5) world.puffExhaust()
769:   } else {
770:     world.moped.update(dt, speed)
771:     sound.revMoped(1200 + Math.abs(speed) * 190)
772:     game.s.stats.km += Math.abs(speed) * dt / 1000
773:   }
774: 
775:   // chase camera
776:   const dist = truck ? 8.2 : 3.7
777:   const height = truck ? 3.7 : 2.1
778:   const camTarget = tmpV2.set(group.position.x - forward.x * dist, height, group.position.z - forward.z * dist)
779:   if (isInGarage(group.position.x, group.position.z)) {
780:     camTarget.x = Math.max(-8.2, Math.min(8.2, camTarget.x))
781:     camTarget.z = Math.max(-5.2, Math.min(5.5, camTarget.z))
782:     camTarget.y = Math.min(4.1, camTarget.y)
783:   }
784:   camera.position.lerp(camTarget, 1 - Math.pow(0.001, dt))
785:   camera.lookAt(group.position.x + forward.x * 1.6, 1.25 + cameraLook, group.position.z + forward.z * 1.6)
786:   camera.fov += ((truck ? 62 : 68) - camera.fov) * 0.08
787:   camera.updateProjectionMatrix()
788:   jobPrompt = jobInteraction()
789:   if (jobPrompt) {
790:     const held = input.keys.has('KeyE') || ui.actionHeld
791:     if (jobPrompt.enabled) {
792:       if (held) {
793:         holdProgress += dt
794:         if (holdProgress >= jobPrompt.hold) { holdProgress = 0; completeJobAction(jobPrompt) }
795:       } else holdProgress = 0
796:     } else { holdProgress = 0; jobPrompt = null }
797:   }
798:   if (jobPrompt) {
799:     ui.setPrompt(jobPrompt.text, { blocked: !jobPrompt.enabled, hold: jobPrompt.enabled ? jobPrompt.hold : 0, progress: holdProgress / jobPrompt.hold })
800:   } else {
801:     ui.setPrompt(`Get out · ${onRoad ? 'ON ROAD' : 'OFF ROAD'}`, { key: 'F' })
802:   }
803:   updateHUD()
804: }
