806: function isOnRoad(x, z) {
807:   if (Math.abs(z - 26) < 4.6 && Math.abs(x) < 155) return true
808:   if (Math.abs(x) < 4.2 && z > 4 && z < 27) return true
809:   if (Math.abs(x - 64) < 3.4 && z > 25 && z < 40) return true
810:   if (Math.abs(x + 58) < 3.4 && z > 25 && z < 40) return true
811:   return false
812: }
813: function isInGarage(x, z) {
814:   return x > -9 && x < 9 && z > -6 && z < 6
815: }
