735: 
736:   // move + collide
737:   const forward = tmpV.set(Math.sin(heading), 0, Math.cos(heading))
738:   const nx = group.position.x + forward.x * speed * dt
739:   const nz = group.position.z + forward.z * speed * dt
740:   let hit = false
741:   for (const tc of world.treeColliders) {
742:     if ((nx - tc.x) ** 2 + (nz - tc.z) ** 2 < (tc.r + (truck ? 1.25 : 0.6)) ** 2) { hit = true; break }
743:   }
744:   if (nx < -160 || nx > 160 || nz < -160 || nz > 160) hit = true
