755:   } else {
756:     group.position.x = nx
757:     group.position.z = nz
758:   }
759:   group.rotation.y = heading
760:   if (truck) {
761:     group.rotation.z = THREE.MathUtils.lerp(group.rotation.z, -steer * 0.025 * Math.min(1, Math.abs(speed) / 8), 0.08)
762:     group.rotation.x = THREE.MathUtils.lerp(group.rotation.x, -axis.y * 0.008, 0.08)
763:     world.truck.group.updateMatrixWorld()
764:     if (Math.abs(speed) > 0.1) world.truck.update(dt, speed)
765:     game.s.truck = { x: group.position.x, z: group.position.z, heading }
766:     game.s.stats.km += Math.abs(speed) * dt / 1000
767:     sound.revEngine(game.idleRpm() + Math.abs(speed) * 95, Math.min(1, game.tuneError().total + game.looseBolts() * 0.04))
768:     if (Math.abs(speed) > 2 && Math.random() < dt * 5) world.puffExhaust()
