252: function loop() {
253:   const dt = Math.min(0.05, clock.getDelta())
254:   const t = performance.now() / 1000
255: 
256:   if (mode === 'title') updateTitle(dt, t)
257:   else if (mode === 'dead') { /* keep rendering the dark room */ }
258:   else if (paused || (ui.panel && ui.panel !== 'torque')) {
259:     updateWorldAmbient(dt, t)
260:     ui.tickTorque(dt)
261:     updateHUD()
262:   } else {
263:     if (mode === 'walk') updateWalk(dt, t)
264:     if (mode === 'drive') updateDrive(dt, t)
265:     updateWorldAmbient(dt, t)
266:     ui.tickTorque(dt)
267:     game.tick(dt)
268:     if (game.dead) { mode = 'dead'; paused = true }
269:     updateHUD()
270:     saveAccum += dt
271:     if (saveAccum > 8) { saveAccum = 0; game.save() }
272:     if (ui.panel === 'tune') ui.updateTuneLive()
273:   }
274:   renderer.render(scene, camera)
275:   input.endFrame()
276: }
