282:     if (Math.random() < dt * 14) world.puffExhaust()
283:   } else if (vehicle === 'truck' && mode === 'drive') {
284:     sound.revEngine(0, 1)
285:   }
286:   if (Math.random() < dt * 0.06 && !ui.panel) {
287:     // occasional creak / settling
288:     if (Math.random() > 0.5) sound.burst({ freq: 500 + Math.random() * 600, q: 3, dur: 0.18, gain: 0.012, rate: 0.4 })
289:   }
290: }
