302: function updateWalk(dt, t) {
303:   camera.fov += (64 - camera.fov) * 0.1
304:   camera.updateProjectionMatrix()
305:   const look = input.consumeLook()
306:   if (!ui.panel) {
307:     player.yaw -= look.x * 0.0022
308:     player.pitch -= look.y * 0.0022
309:     player.pitch = Math.max(-1.35, Math.min(1.35, player.pitch))
310:   }
311:   const axis = ui.panel ? { x: 0, y: 0 } : input.axis()
312:   const fatigue = game.s.meters.fatigue
313:   const sprint = input.sprint() && fatigue < 80 && game.s.meters.stamina !== 0
314:   const speedWalk = (sprint ? 4.2 : 2.7) * (1 - Math.min(0.35, fatigue / 280)) * (game.s.health < 35 ? 0.72 : 1)
315:   const forward = tmpV.set(-Math.sin(player.yaw), 0, -Math.cos(player.yaw))
316:   const right = tmpV2.set(Math.cos(player.yaw), 0, -Math.sin(player.yaw))
317:   const wish = new THREE.Vector3()
318:   wish.addScaledVector(forward, -axis.y).addScaledVector(right, axis.x)
319:   if (wish.lengthSq() > 0) wish.normalize().multiplyScalar(speedWalk * dt)
320:   const moved = tryMove(wish.x, wish.z)
321:   const movedLen = Math.hypot(moved.x, moved.z)
322:   player.stepDist += movedLen
323:   if (movedLen > 0.0005) {
324:     player.bob += dt * (sprint ? 10 : 7.2)
325:     if (player.stepDist > 1.6) { player.stepDist = 0; sound.step(sprint ? 1.4 : 1) }
326:   } else {
327:     player.bob *= 0.9
328:   }
329:   const bobY = Math.sin(player.bob) * (sprint ? 0.045 : 0.028)
330:   const bobX = Math.cos(player.bob * 0.5) * 0.018
331:   camera.position.set(player.pos.x + right.x * bobX, player.pos.y + bobY, player.pos.z + right.z * bobX)
332:   camera.rotation.set(player.pitch, player.yaw, Math.sin(player.bob * 0.5) * 0.004)
333: 
334:   updateInteractions(dt)
335:   updateMountHints()
336:   updateVehicleProximity()
337: }
