541: function installPart(part) {
542:   if (part === 'wheels' && !game.hasPart('wheels')) {
543:     // wheels are a set
544:   }
545:   if (!game.installPart(part)) { ui.toast('You do not have that part.', 'bad'); return }
546:   world.truck.setPart(part, true)
547:   world.truck.makeBolts(part, game.s.bolts[part])
548:   sound.clunk()
549:   ui.toast(`${PART_INFO[part].name} mounted. Torque it to spec.`, '')
550:   game.save()
