567: function startTorque(part, index) {
568:   const info = PART_INFO[part]
569:   if (!game.s.parts[part]) return
570:   if (!game.s.bolts[part]) game.s.bolts[part] = new Array(info.bolts).fill(null)
571:   if (index < 0) return
572:   if (tool !== info.tool) {
573:     sound.error()
574:     ui.toast(`Need a ${info.tool}mm socket.`, 'bad')
575:     return
576:   }
577:   const [lo, hi] = info.torque
578:   ui.showTorque({ part, label: info.name, lo, hi, index, total: info.bolts })
579:   if (ui.torque) ui.torque.startedAt = performance.now()
580: }
