582: function finishPart(part) {
583:   if (ui.panel === 'torque') ui.hideTorque()
584:   sound.success()
585:   const loose = game.s.bolts[part].filter(v => v === 'loose').length
586:   const strip = game.s.bolts[part].filter(v => v === 'stripped').length
587:   if (!loose && !strip) ui.toast(`${PART_INFO[part].name} seated at spec.`, 'good')
588:   else ui.toast(`Done — but ${loose} loose, ${strip} stripped. Fix them.`, 'bad')
589:   game.save()
590:   updateHUD()
591: }
